    "passage": "Job Posting: Senior Financial Analyst — Whitmore Group\n\nWhitmore Group is seeking an experienced Senior Financial Analyst to join our growing investment team in Chicago. The ideal candidate holds a CFA certification and has at least five years of experience in equity research. Responsibilities include preparing quarterly earnings reports, building financial models, and presenting investment recommendations to senior management. Although the position is based in our downtown office, candidates who live within commuting distance may request two remote workdays per week after a three-month probationary period. Salary is competitive and includes an annual performance bonus. Interested applicants should submit a resume and cover letter by August 15. Only shortlisted candidates will be contacted for an interview."
