    "passage": "Minutes of the Product Development Meeting — July 10\n\nAttendees: R. Kim, S. Patel, T. Nguyen, L. Osei\n\nThe meeting opened with a review of the delayed launch of the SmartHome hub, originally scheduled for September but now pushed to November due to a shortage of semiconductor chips from our supplier in Taiwan. S. Patel reported that an alternative supplier in Vietnam has been identified and could reduce the delay to only three weeks if approved by next Friday. T. Nguyen raised concerns that switching suppliers might affect product quality, so a sample batch will be tested before any final decision. L. Osei will present the marketing plan adjustments at the next meeting on July 17. The team agreed to reconvene once testing results are available."
