    "passage": "Notice to All Building Tenants\n\nThe management office would like to inform tenants that the main elevator in the north wing will be out of service for scheduled maintenance from July 22 to July 26. During this period, tenants on floors 5 through 12 are asked to use the south wing elevator or the stairwell near the lobby entrance. We recognize that this may cause some inconvenience, particularly for deliveries, and have arranged for the loading dock staff to assist with larger packages during business hours. The south elevator has recently been inspected and is fully operational. We apologize for any disruption and thank you for your understanding as we complete this necessary upgrade."
