    "passage": "Dear Valued Customer,\n\nWe are writing to inform you that your invoice #7734 for the office furniture order remains unpaid as of today, 45 days past the due date. Our records show that we sent two previous reminders, on June 15 and July 1, but have not yet received a response. As a result, a late payment fee of 2 percent has been added to your outstanding balance. If payment is not received within 10 business days, your account will be placed on hold, and future orders will require prepayment. We value our business relationship and would like to resolve this matter promptly. Please contact our billing department at your earliest convenience to discuss payment options."
