    "passage": "Warranty Policy Update — TechNest Electronics\n\nEffective September 1, all TechNest laptops will come with an extended two-year warranty, up from the previous one-year coverage. This change applies only to units purchased after the effective date; laptops bought earlier will retain their original one-year warranty terms. The extended warranty covers manufacturing defects and battery failure but does not cover accidental damage, such as cracked screens or liquid spills. Customers wishing to add accidental damage protection may purchase a separate protection plan at checkout. We believe this update reflects our commitment to product quality and customer satisfaction. Existing customers with questions about their current warranty status should contact customer support."
